import ctypes

def copy_matrix(dest, src):
    if dest.size != src.size:
        return 0
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    gsl_matrix_memcpy = gsl.gsl_matrix_memcpy
    gsl_matrix_memcpy.argtypes = [ctypes.POINTER(GSLMatrix), ctypes.POINTER(GSLMatrix)]
    gsl_matrix_memcpy.restype = ctypes.c_int
    return gsl_matrix_memcpy(dest, src)

class GSLMatrix:
    def __init__(self, np_array):
        self.np_array = np_array
        self.size = len(np_array)
    def memcpy(self, other):
        if self.size != other.size:
            return 0
        dest = GSLMatrix(self.np_array)
        src = GSLMatrix(other.np_array)
        return copy_matrix(dest, src)

