import numpy as np

class gsl_matrix(object):
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.data = []

    def numpy_to_gsl_matrix(self, np_array):
        if np_array.shape[0] != self.rows or np_array.shape[1] != self.cols:
            raise ValueError("Input array must have same number of rows and columns as matrix")
        for i in range(self.rows):
            for j in range(self.cols):
                self.data.append(np_array[i, j])

    def gsl_to_numpy_matrix(self):
        np_array = np.zeros((self.rows, self.cols))
        for i in range(self.rows):
            for j in range(self.cols):
                np_array[i, j] = self.data[i*self.cols + j]
        return np_array

class gsl_vector(object):
    def __init__(self, size):
        self.size = size
        self.data = []

    def numpy_to_gsl_vector(self, np_array):
        if np_array.shape[0] != self.size:
            raise ValueError("Input array must have same number of elements as vector")
        for i in range(self.size):
            self.data.append(np_array[i])

    def gsl_to_numpy_vector(self):
        np_array = np.zeros((self.size))
        for i in range(self.size):
            np_array[i] = self.data[i]
        return np_array

