class GSLHistogram(ctypes.Structure):
    _fields_ = [("size", ctypes.c_int),
                ("data", ctypes.POINTER(ctypes.c_double))]

gsl = None
gslcblas = None

def compute_histogram_statistics(histogram):
    global gsl, gslcblas

    # Load the GSL libraries if not already loaded
    if gsl is None:
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    if gslcblas is None:
        gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)

    # Create a GSL histogram object from the input histogram
    gsl_histogram = GSLHistogram()
    gsl_histogram.size = ctypes.c_int(histogram.size())
    gsl_histogram.data = (ctypes.POINTER(ctypes.c_double))(*[ctypes.c_double(x) for x in histogram.values()])

    # Compute the mean, standard deviation, and sum of the histogram using GSL functions
    gsl_mean = gsl.gsl_histogram_mean(gsl_histogram)
