def compute_moving_median(data, window_size):
    # Initialize a median accumulator
    med = gsl.gsl_median_accumulator()

    # Insert data points into the median accumulator
    for i in range(len(data)):
        if i + window_size - 1 < len(data):
            gsl.gsl_median_accumulator_add(med, data[i])
        else:
            break

    # Retrieve the median using ctypes to load and call the corresponding C functions from the compiled dynamic library
    medians = []
    for i in range(len(data) - window_size + 1):
        medians.append(gsl.gsl_median_accumulator_get(med))
        gsl.gsl_median_accumulator_reset(med)

    return medians

