class gsl_vector(ctypes.Structure):
    _fields_ = [("data", ctypes.POINTER(ctypes.c_double)), ("stride", ctypes.c_size_t), ("size", ctypes.c_size_t)]

class gsl_eigen_hermv_workspace(ctypes.Structure):
    _fields_ = [("n", ctypes.c_size_t), ("size", ctypes.c_size_t), ("max_bidiag_alloc", ctypes.c_size_t)]

class gsl_complex(ctypes.Structure):
    _fields_ = [("dat", ctypes.POINTER(ctypes.c_double)), ("imag", ctypes.c_double)]

def compute_eigen(matrix, size):
    matrix_ptr = (gsl_matrix_complex * size * size).from_buffer(matrix)
    vector_ptr = gsl_vector()
    workspace_ptr = gsl_eigen_hermv_workspace()
    eigenvalues = []
    eigenvectors = []

    for i in range(size):
        for j in range(size):
            ctype_complex = gsl_complex((ctypes.c_double * 2)(matrix[i][j].real, matrix[i][j].imag))
            gsl_matrix_set(matrix_ptr, i, j, ctype_complex)

    status = gsl_eigen_hermv(matrix_ptr, vector_ptr, workspace_ptr)

    if status != 0:
        return None

