def forward_transform(data):
	size = len(data)
	for i in range(size):
		data[i] = data[i] * 2.0
	return data

def zero_smallest(data, threshold):
	smallest = None
	for i in range(len(data)): 
		if smallest is None or abs(data[i]) < smallest: 
			smallest = abs(data[i])
	for i in range(len(data)): 
		if abs(data[i]) <= threshold * smallest:
			data[i] = 0.0
	return data

def inverse_transform(data):
	size = len(data)
	for i in range(size):
		data[i] = data[i] / 2.0
	return data

