from typing import List, Union

class GSLMatrix:
    def __init__(self, matrix: List[List[float]]):
        self._matrix = matrix
        self._gsl_matrix = None

    @property
    def gsl_matrix(self) -> ctypes.c_void_p:
        if not self._gsl_matrix:
            self._gsl_matrix = GSLMatrix._create_gsl_matrix(self._matrix)
        return self._gsl_matrix

    @staticmethod
    def _create_gsl_matrix(matrix: List[List[float]]) -> ctypes.c_void_p:
        # Load the GSL library dynamically
        gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        # Create the GSL matrix
        gsl_matrix = gsl.gsl_matrix_alloc(len(matrix), len(matrix[0]))

        # Fill the GSL matrix with the values from the input matrix
        for i in range(len(matrix)):
            for j in range(len(matrix[i])):
                gslcblas.gsl_matrix_set(gsl_matrix, i, j, ctypes.c_float(matrix[i][j]))

        return gsl_matrix

    def __del__(self):
        if self._gsl_matrix:
            gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
            gsl.gsl_matrix_free(self._gsl_matrix)

def matrix_to_gsl(matrix: List[List[float]]) -> GSLMatrix:
    return GSLMatrix(matrix)

def gsl_matrix_to_numpy(gsl_matrix: ctypes.c_void_p) -> List[List[float]]:
    # Load the GSL library dynamically
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    # Get the dimensions of the GSL matrix
    nrows = gsl.gsl_matrix_nrow(gsl_matrix)
    ncols = gsl.gsl_matrix_ncol(gsl_matrix)

    # Allocate a numpy array to store the result
    result = [[0] * ncols for _ in range(nrows)]

    # Iterate over the elements of the GSL matrix and copy them into the numpy array
    for i in range(nrows):
        for j in range(ncols):
            result[i][j] = gsl.gsl_matrix_get(gsl_matrix, i, j)

    return result

def compute_matrix_exponential(matrix: Union[List[List[float]], GSLMatrix], mode: int) -> List[List[float]]:
    # Load the GSL library dynamically
    gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    # Convert the input matrix to a GSL matrix
    if isinstance(matrix, List):
        matrix = matrix_to_gsl(matrix)

    # Compute the matrix exponential using GSL
    gsl_matrix_exp = gslcblas.gsl_linalg_exponential_ss(gsl.gsl_matrix_alloc(len(matrix), len(matrix[0])), matrix.gsl_matrix, ctypes.c_int(mode))

    # Convert the result back to a numpy array and return it
    return gsl_matrix_to_numpy(gsl_matrix_exp)

