def bspline_wlssolve(x, y, weights=None):
    if len(x) != len(y) or (weights is not None and len(x) != len(weights)):
        return None

    x = (ctypes.c_double * len(x))(*x)
    y = (ctypes.c_double * len(y))(*y)
    if weights is not None:
        weights = (ctypes.c_double * len(weights))(*weights)

    libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    libgsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    gsl_vector = libgsl.gsl_vector_alloc(len(x))
    gsl_bspline_workspace = libgsl.gsl_bspline_workspace_alloc(len(x))

    try:
        for i in range(len(x)):
            gsl_vector[i] = x[i]
        for j in range(len(y)):
            gsl_vector[j] = y[j]
        if weights is not None:
            for k in range(len(weights)):
                gsl_vector[k] = weights[k]
        gsl_bspline_wlssolve(gsl_bspline_workspace, gsl_vector)
    finally:
        libgsl.gsl_bspline_workspace_free(gsl_bspline_workspace)
        libgslcblas.gsl_vector_free(gsl_vector)

    coefficients = []
    for i in range(len(x)):
        coefficients.append(gsl_bspline_workspace[i])

    return coefficients

