def cholesky_decomposition(matrix):
    # Check if input matrix is positive definite
    if not is_positive_definite(matrix):
        return None

    # Load GSL libraries
    gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    # Define GSLMatrix class
    class GSLMatrix:
        def __init__(self, matrix):
            self.matrix = matrix

        def is_positive_definite(self):
            return gsl.is_positive_definite(self)

        def cholesky_decomp(self):
            result = GSLMatrix(gsl.cholesky_decomp(self))
            if not result:
                return None
            else:
                return result.matrix

    # Convert input matrix to GSLMatrix object
    gsl_matrix = GSLMatrix(matrix)

    # Perform Cholesky decomposition
    cholesky_decomposition = gsl_matrix.cholesky_decomp()

    # Return lower triangular matrix resulting from the decomposition
    return cholesky_decomposition

